Style: documentary realism, imperfect framing, natural lighting, no visual effects, 4K.', null, null, 'missing', 4, 'keep', 'pass', 'aspirational', 'photoreal', null, 'high-fps-slowmo', 'none', null, 'offline real-world gate: real-world: documentary, handheld', 'seedance_2.0', '@LudovicCreator', 'https://x.com/LudovicCreator', null, null),
