('APX-S-2147-1', 'APX-C-2147', 1, null, null, null, 'Shot on ALEXA 65mm anamorphic lens. Photorealistic cinematic quality. Aspect ratio 2.39:1 widescreen. Teal shadows, warm amber highlights. Film grain. Tokyo neon dusk. Lens flares, motion blur. Dolby Vision HDR. 0.0s–2.5s: Extreme low-angle tracking shot — a hyper-focused street female food chef sprints at impossible speed through a neon-lit Tokyo alley, clutching a steaming bowl of ramen.', null, null, 'Teal shadows, warm amber highlights. 0.0s–2.5s: shot — a hyper-focused street female food chef sprints at impossible speed through a neon-lit Tokyo alley, clutching a steaming bowl of ramen.', 'chef', 'sprinting; racing', 'ramen', 'featured', 'tokyo, alley', null),
('APX-S-2147-2', 'APX-C-2147', 2, null, null, null, 'Crisp apron flapping, sleeves rolled, sneakers splashing through puddles. Camera shakes aggressively behind them. Steam trails like smoke. Neon signs streak across frame. Their face — intense, locked-in, slightly unhinged determination. 2.6s–5.0s: Whip-pan — they shoulder-check a stack of plastic crates.', null, null, 'Their face — intense, locked-, slightly unhinged determination. 2.6s–5.0s: — they shoulder-check a stack of plastic crates.', null, null, null, null, null, 'intense'),
('APX-S-2147-3', 'APX-C-2147', 3, null, null, null, 'TIME REMAP: slow-motion chaos — vegetables, bowls, and chopsticks explode into the air. Broth ripples in perfect cinematic detail without spilling. They tilt the bowl mid-run, saving every drop. Quick glance back, dead serious. Continue sprint. 5.1s–7.5s: Drone shot — they leap across narrow alley gaps between buildings.', null, null, 'They tilt the bowl mid-run, saving every drop. 5.1s–7.5s: — they leap across narrow alley gaps between buildings.', null, 'sprinting; leaping', 'vegetables; broth', 'featured', 'alley', null),
('APX-S-2147-4', 'APX-C-2147', 4, null, null, null, 'SLOW MOTION: steam spirals upward into neon light. A cat jumps out of the way. Laundry lines ripple. They casually garnish the ramen mid-air with one hand — flawless precision. 7.6s–10.0s: 360° orbital shot — they slide across the hood of a parked car, spin, land clean. One sandal nearly slips off but is caught mid-motion.', null, null, 'They casually garnish the ramen mid-air with one hand — flawless precision. 7.6s–10.0s: 360° orbital shot — they slide across the hood of a parked car, spin, land clean.', 'animal-character', 'leaping; sliding; garnishing', 'ramen', 'featured', null, null),
('APX-S-2147-5', 'APX-C-2147', 5, null, null, null, 'They adjust grip on the bowl, completely composed. 10.1s–13.0s: First-person POV — a small ramen shop door rushes forward. SMASH CUT: door slams open. Steam floods the frame. They step in, perfectly calm now. Place the bowl gently on the counter. Slow push-in. Low-angle shot. They look at the customer: “Still hot.” Customer sits in stunned silence as steam rises dramatically.', null, null, 'They adjust grip on the bowl, completely composed. 10.1s–13.0s: First-person POV — a small ramen shop door rushes forward. They step, perfectly calm now.', 'guest', null, 'ramen', 'featured', 'ramen shop', 'calm'),
('APX-S-2141-1', 'APX-C-2141', 1, null, null, null, 'First-person POV from a jet ski rider in the middle of a violent tropical storm. Hands grip the handlebars while massive waves tower on both sides. Rain and ocean spray slam across the visor. At the 2-second mark a gigantic rogue wave rises ahead like a moving wall.', null, null, 'First-person POV from a jet ski rider in the middle of a violent tropical storm. Hands grip the handlebars while massive waves tower on both sides. Rain and ocean spray slam across the visor.', 'driver', null, null, null, 'tower, ocean', null),
('APX-S-2141-2', 'APX-C-2141', 2, null, null, null, 'The rider accelerates up the wave face and launches off the crest, airborne above the stormy ocean. The jet ski slams down into the trough and continues racing through the chaos. Storm ocean POV ride, rogue wave launch, cinematic water physics, 4K.', null, null, 'The rider accelerates up the wave face and launches off the crest, airborne above the stormy ocean.', 'driver', 'racing', null, null, 'ocean', null),
